import{_ as e,o as d,c as o,a2 as c}from"./chunks/framework.CvydjLy7.js";const h=JSON.parse('{"title":"五、本教程的代码约定","description":"","frontmatter":{"title":"五、本教程的代码约定"},"headers":[],"relativePath":"ch00/05.md","filePath":"ch00/05.md","lastUpdated":1789497795000}'),a={name:"ch00/05.md"};function r(s,t,i,n,l,p){return d(),o("div",null,[...t[0]||(t[0]=[c('<h1 id="五、本教程的代码约定" tabindex="-1">五、本教程的代码约定 <a class="header-anchor" href="#五、本教程的代码约定" aria-label="Permalink to &quot;五、本教程的代码约定&quot;">​</a></h1><p>为了不在每篇重复解释，这里把全局约定一次讲清，后续章节直接遵循。</p><table tabindex="0"><thead><tr><th>约定</th><th>内容</th><th>原因</th></tr></thead><tbody><tr><td>包名</td><td><code>com.example.activity</code></td><td>占位用法。实际项目替换成自己的组织域名倒写</td></tr><tr><td>统一响应体</td><td><code>ApiResponse&lt;T&gt;</code>，字段为 <code>code</code> / <code>message</code> / <code>data</code>，<code>code = 0</code> 表示成功</td><td>前端只需判断一个字段就能区分成功与失败</td></tr><tr><td>分页结果</td><td><code>PageResult&lt;T&gt;</code>，字段为 <code>items</code> / <code>total</code> / <code>page</code> / <code>size</code></td><td>不直接暴露框架的分页对象，避免换数据访问技术时接口跟着变</td></tr><tr><td>HTTP 状态码</td><td>传输层语义用状态码（200 / 201 / 400 / 404），业务语义用 <code>code</code></td><td>两者分工明确，网关和前端都能各自利用</td></tr><tr><td>时间类型</td><td>实体统一用 <code>LocalDateTime</code>，对外格式由字段上的 <code>@JsonFormat</code> 指定</td><td><code>spring.jackson.date-format</code> 对 JSR-310 类型不生效，必须用注解</td></tr><tr><td>实体标识</td><td>业务表统一带 <code>created_at</code> / <code>updated_at</code>；删除采用状态字段而非物理删除</td><td>便于审计与恢复</td></tr></tbody></table><blockquote><p><strong>下一篇要做什么</strong></p><p>下一篇对照官方的 Getting Started 与 Tutorial，从零建起第一个 Spring Boot 应用：配置 Maven 工程、写第一个 REST 接口、理解它为什么能跑起来、打成可执行 jar。案例项目 <code>activity-server</code> 也会在这一篇正式登场。</p></blockquote>',4)])])}const m=e(a,[["render",r]]);export{h as __pageData,m as default};
